268	type ResourceType = 'venue' | 'equipment' | 'person';
269	type BookingStatus = 'active' | 'cancelled';
270	type WaitlistStatus = 'waiting' | 'fulfilled' | 'cancelled';
271	type WaitlistKind = 'fixed' | 'flexible'; // 固定时段候补 / 弹性时段候补
272	type ClosureStatus = 'active' | 'cancelled';
273	type BatchOpStatus = 'active' | 'undone'; // 批量改期操作：未撤销 / 已撤销
274	
275	interface ResourceRec {
276	  id: string;
277	  type: ResourceType;
278	  name: string;
279	  open: Array<[string, string]>;
280	}
281	
282	interface BookingRec {
283	  id: string;
284	  resourceIds: string[];
285	  start: string;
286	  end: string;
287	  status: BookingStatus;
288	  seriesId?: string;
289	}
290	
291	interface SeriesRec {
292	  id: string;
293	}
294	
295	interface WaitlistRec {
296	  id: string; // 候补标识 W0001…，稳定且不复用
297	  kind: WaitlistKind; // fixed=固定时段；flexible=弹性时段（窗口内寻找最早连续时长）
298	  resourceIds: string[]; // 原请求资源（按标识排序）
299	  start: string; // 原请求开始时间；弹性项为窗口开始
300	  end: string; // 原请求结束时间；弹性项为窗口结束
301	  durationMinutes?: number; // 仅弹性项：所需连续时长（正整数分钟，不超过窗口长度）
302	  status: WaitlistStatus;
303	  seq: number; // 登记序号：1 基，列表与处理均按此稳定排序，重启后仍在
304	  bookingId?: string; // 已兑现时关联的普通预约标识
305	}
306	
307	interface ClosureRec {
308	  id: string; // 停用标识 C0001…，稳定且不复用
309	  resourceId: string; // 单个已登记资源
310	  start: string;
311	  end: string;
312	  status: ClosureStatus;
313	}
314	
315	// 一次批量改期提交中的单项快照（按清单顺序）
316	interface BatchOpItem {
317	  bookingId: string;
318	  seriesId?: string; // 提交时的系列归属（无系列则不含）
319	  before: {start: string; end: string; resourceIds: string[]}; // 改期前安排
320	  after: {start: string; end: string; resourceIds: string[]}; // 改期后安排（提交目标）
321	}
322	
323	interface BatchOpRec {
324	  id: string; // 批量改期操作标识 O0001…，稳定且不复用（即使记录已撤销）
325	  status: BatchOpStatus;
326	  items: BatchOpItem[]; // 按提交（清单）顺序
327	}
328	
329	// 一次 iCalendar 导入建立的“UID -> 预约/系列”永久关联：
