4688	// 解析整个 iCalendar 文件；任何结构错误、关键属性重复或缺失都抛出 BizError（整批失败）。
4689	// 同一 UID 允许一个不带 RECURRENCE-ID 的按周主事件配若干例外 VEVENT（各带单个
4690	// RECURRENCE-ID 与改期后 DTSTART/DTEND，可位于主事件之前或之后）；其余重复 UID 拒绝。
4691	function parseIcalFile(text: string, file: string): IcalEvent[] {
4692	  const bad = (reason: string): never => {
4693	    throw new BizError(`iCalendar 文件 ${file} 无法导入：${reason}（整批未导入，数据未改动）`);
4694	  };
4695	  const lines = unfoldIcalLines(text, bad);
4696	  if (lines.length === 0) bad('文件为空');
4697	
4698	  const rawEvents: RawVevent[] = [];
4699	  let inCalendar = false;
4700	  let calendarEnded = false;
4701	  let versionSeen = false;
4702	  let inEvent = false;
4703	  let curUid: string | undefined;
4704	  let curStart: {raw: string; min: number} | undefined;
4705	  let curEnd: {raw: string; min: number} | undefined;
4706	  let curRrule: string | undefined; // RRULE 原文（至多一条）
4707	  let curExdates: Array<{raw: string; min: number}> = []; // 多行 EXDATE 合并后的候选时间
4708	  let curRecurrenceId: {raw: string; min: number} | undefined;
4709	
4710	  const closeEvent = (): void => {
