31	
32	interface CliResult {
33	  status: number;
34	  stdout: string;
35	  stderr: string;
36	}
37	
38	function runCli(dataFile: string, args: string[]): CliResult {
39	  const r = spawnSync(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8'});
40	  if (r.error) throw r.error;
41	  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
42	}
43	
44	// 异步并发入口：真实并行子进程竞争同一数据文件
45	function runCliAsync(dataFile: string, args: string[], cwd?: string): Promise<CliResult> {
46	  return new Promise((resolveP, reject) => {
47	    const p = spawn(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8', cwd});
48	    let stdout = '';
49	    let stderr = '';
50	    p.stdout.on('data', (d) => (stdout += d));
51	    p.stderr.on('data', (d) => (stderr += d));
52	    p.on('error', reject);
53	    p.on('close', (status) => resolveP({status: status ?? -1, stdout, stderr}));
54	  });
55	}
56	
57	// 可中途终止的真实子进程：返回句柄与结果 Promise；env 用于注入测试同步点目录
58	// （SHIFTBOOK_TEST_SYNC_DIR，应用内测试钩子在指定交接点写 ready 标记并等待 go 标记）
59	function spawnCli(
60	  dataFile: string,
61	  args: string[],
62	  env?: Record<string, string>,
63	): {child: ChildProcess; result: Promise<CliResult>} {
64	  const child = spawn(process.execPath, [APP, '--data', dataFile, ...args], {
65	    encoding: 'utf8',
66	    env: {...process.env, ...env},
67	  });
68	  let stdout = '';
69	  let stderr = '';
70	  child.stdout.on('data', (d) => (stdout += d));
71	  child.stderr.on('data', (d) => (stderr += d));
72	  const result = new Promise<CliResult>((resolveP, reject) => {
73	    child.on('error', reject);
74	    child.on('close', (status) => resolveP({status: status ?? -1, stdout, stderr}));
75	  });
76	  return {child, result};
77	}
78	
79	// 明确同步点：等待子进程在交接点写下的 ready 标记出现（非随机延时）
80	async function waitForSyncPoint(path: string, ctx: string, timeoutMs = 15000): Promise<void> {
81	  const deadline = Date.now() + timeoutMs;
82	  while (!existsSync(path)) {
83	    if (Date.now() > deadline) throw new Error(`等待同步点超时: ${ctx}（${path}）`);
84	    await new Promise((r) => setTimeout(r, 10));
85	  }
86	}
87	
88	// 真正终止子进程（SIGKILL）并等待其退出；进程结束时来不及执行任何释放逻辑
89	function killAndWait(child: ChildProcess): Promise<void> {
90	  return new Promise((resolveP) => {
91	    if (child.exitCode !== null || child.signalCode !== null) return resolveP();
92	    child.once('close', () => resolveP());
93	    child.kill('SIGKILL');
94	  });
95	}
