113	function addResource(df: string, name: string, open: Array<[string, string]> = OPEN_ALL): void {
114	  const args = ['add-resource', '--type', 'venue', '--name', name];
115	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
