123	// 与应用一致的锁文件路径：规范路径（解析相对/./..与符号链接）+ .lock
124	function lockPathOf(df: string, cwd?: string): string {
125	  const abs = resolve(cwd ?? process.cwd(), df);
126	  let canonical: string;
127	  try {
128	    canonical = realpathSync(abs);
129	  } catch {
130	    canonical = join(realpathSync(dirname(abs)), basename(abs));
131	  }
132	  return `${canonical}.lock`;
133	}
134	
135	// 与应用一致的恢复协调文件路径：<锁文件>.recover
136	function recoveryPathOf(df: string, cwd?: string): string {
137	  return `${lockPathOf(df, cwd)}.recover`;
138	}
139	
140	// 用一个真实存活进程持有指定数据文件的写入保护；release 结束该进程并等待其退出
141	function holdLock(df: string, t: {after: (fn: () => void) => void}, cwd?: string): {
142	  child: ChildProcess;
143	  lockPath: string;
144	  release: () => Promise<void>;
145	} {
146	  const child = spawn(process.execPath, ['-e', 'setInterval(() => {}, 1000)'], {stdio: 'ignore'});
147	  const lockPath = lockPathOf(df, cwd);
148	  const info = {
149	    pid: child.pid,
150	    host: hostname(),
151	    dataFile: resolve(cwd ?? process.cwd(), df),
152	    acquiredAt: new Date().toISOString(),
153	  };
154	  writeFileSync(lockPath, JSON.stringify(info) + '\n', {encoding: 'utf8', flag: 'wx'});
155	  let released = false;
156	  const release = (): Promise<void> => {
157	    if (released) return Promise.resolve();
158	    released = true;
159	    return new Promise((resolveP) => {
160	      child.once('close', () => resolveP());
161	      try {
162	        child.kill('SIGKILL');
163	      } catch {
164	        resolveP();
165	      }
166	    });
167	  };
168	  t.after(() => {
169	    void release();
170	    rmSync(lockPath, {force: true});
171	  });
172	  return {child, lockPath, release};
173	}
174	
175	// 一个已经退出的进程标识（用于构造残留保护）
176	function deadPid(): Promise<number> {
177	  return new Promise((resolveP, reject) => {
178	    const child = spawn(process.execPath, ['-e', ''], {stdio: 'ignore'});
179	    child.on('error', reject);
180	    child.on('close', () => resolveP(child.pid!));
181	  });
182	}
