720	  // 由新进程查询最终安排并核对
721	  const day = ok(df, ['list-bookings', '--date', '2026-10-12'], '恢复交接后按日查询');
722	  assert.match(day.stdout, /共 2 条/);
723	  assert.match(day.stdout, /B0001 \[已预约\] 2026-10-12T09:00 → 2026-10-12T10:00/);
724	  assert.match(day.stdout, /B0002 \[已预约\] 2026-10-12T10:00 → 2026-10-12T11:00/);
725	  assert.deepEqual(leftoverLocks(dir), [], '不残留锁或协调文件');
726	});
727	
728	// ---------------------------------------------------------------------------
729	// 12. 真正终止协调中的恢复进程：残留协调文件由后续恢复安全清理
